{
 "pdf_page": 191,
 "book_page": 161,
 "verified_by": "claude-opus-5",
 "verified_on": "2026-09-05",
 "entries": [
  {
   "entry": 0,
   "root": "Gheslo",
   "verdict": "confirmed",
